(function () {
// Browser-only media plan PPT generator for GitHub Pages.
// The page loads SheetJS, JSZip, and PptxGenJS from local files in ./vendor.

const ORANGE      = "F26522";   // OAP brand orange
const DARK_ORANGE = "C24E0F";   // darker orange for depth
const BLACK       = "1A1A1A";   // near-black
const CHARCOAL    = "2D2D2D";   // slightly lighter black
const WHITE       = "FFFFFF";
const OFF_WHITE   = "F5F5F5";
const LIGHT_GRAY  = "E8E8E8";
const MID_GRAY    = "888888";
const DARK_GRAY   = "444444";
const BORDER_GRAY = "DDDDDD";
const LOGO_DATA = "image/png;base64,";

// ── Logo base64 ────────────────────────────────────────────────────────────────
const LOGO_B64 = "image/jpeg;base64,";

// ── Read Excel ─────────────────────────────────────────────────────────────────
function getMapUrl(lat, lng) {
  return `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
}
function getStreetUrl(lat, lng) {
  return `https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${lat},${lng}`;
}
function formatCurrency(val) {
  if (!val && val !== 0) return "—";
  return "₹" + Number(val).toLocaleString("en-IN");
}
function formatDim(w, h) {
  if (!w && !h) return "—";
  return `${w || "?"} × ${h || "?"} ft`;
}
const mkShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 });


function rowsFromExcelBuffer(excelBuffer) {
  const wb = window.XLSX.read(excelBuffer, { type: "array" });
  const ws = wb.Sheets[wb.SheetNames[0]];
  const data = window.XLSX.utils.sheet_to_json(ws);

  if (data.length === 0) {
    throw new Error("No data found in the first sheet. Please upload a populated Excel file.");
  }

  return data;
}

async function generateMediaPlanFromBuffer(excelBuffer) {
  const data = rowsFromExcelBuffer(excelBuffer);
  return generateMediaPlanFromRows(data);
}

async function generateMediaPlanFromRows(data) {
const PptxGen = window.pptxgen || window.PptxGenJS || window.pptxgenjs;
if (!PptxGen) throw new Error("PPT generator library did not load.");
const pres  = new PptxGen();
pres.layout = "LAYOUT_WIDE"; // 13.3 × 7.5 inches
pres.title  = "OAP Mediatech — Media Plan";

const SW = 13.3;
const SH = 7.5;
const PHOTO_X = 4.35;
const PHOTO_Y = 0.15;
const PHOTO_W = 8.5;
const PHOTO_H = 7.2;

pres.defineSlideMaster({
  title: "MEDIA_PLAN",
  background: { color: OFF_WHITE },
  objects: [
    {
      placeholder: {
        text: "",
        options: {
          name: "mediaPhoto",
          type: "image",
          x: PHOTO_X,
          y: PHOTO_Y,
          w: PHOTO_W,
          h: PHOTO_H,
        },
      },
    },
  ],
});

data.forEach((row, idx) => {
  const lat       = row["Lat"]  || 0;
  const lng       = row["Long"] || 0;
  const mapUrl    = getMapUrl(lat, lng);
  const streetUrl = getStreetUrl(lat, lng);
  const slideNum  = String(row["Sl.No"] || idx + 1).padStart(2, "0");

  const slide = pres.addSlide({ masterName: "MEDIA_PLAN" });

  // ── LEFT PANEL (black) ─────────────────────────────────────────────────────
  const leftW = 4.1;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: leftW, h: SH,
    fill: { color: BLACK }, line: { color: BLACK }
  });

  // Orange accent strip at left edge
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.07, h: SH,
    fill: { color: ORANGE }, line: { color: ORANGE }
  });

  // ── LOGO area ───────────────────────────────────────────────────────────────
  slide.addImage({
    data: LOGO_DATA,
    x: 0.27, y: 0.12, w: 1.65, h: 0.62,
    sizing: { type: "contain", w: 1.65, h: 0.62 }
  });

  // Orange separator under logo
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.07, y: 0.9, w: leftW - 0.07, h: 0.04,
    fill: { color: ORANGE }, line: { color: ORANGE }
  });

  // ── Slide number badge ──────────────────────────────────────────────────────
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftW - 0.56, y: 0.94, w: 0.5, h: 0.34,
    fill: { color: ORANGE }, line: { color: ORANGE }
  });
  slide.addText(slideNum, {
    x: leftW - 0.56, y: 0.94, w: 0.5, h: 0.34,
    fontSize: 11, bold: true, color: WHITE, align: "center", valign: "middle", margin: 0
  });

  // ── City ────────────────────────────────────────────────────────────────────
  const city  = (row["City"]  || "").toUpperCase();

  slide.addText(city, {
    x: 0.2, y: 1.16, w: leftW - 0.7, h: 0.42,
    fontSize: 24, bold: true, color: WHITE, align: "left", margin: 0
  });

  // Orange thin divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.2, y: 1.88, w: leftW - 0.4, h: 0.025,
    fill: { color: ORANGE }, line: { color: ORANGE }
  });

  // ── Location ────────────────────────────────────────────────────────────────
  slide.addText("LOCATION", {
    x: 0.2, y: 1.96, w: leftW - 0.3, h: 0.2,
    fontSize: 7, bold: true, color: ORANGE, charSpacing: 2.5, align: "left", margin: 0
  });
  slide.addText(row["Location"] || "—", {
    x: 0.2, y: 2.16, w: leftW - 0.3, h: 0.65,
    fontSize: 10.5, color: WHITE, align: "left", valign: "top", wrap: true, margin: 0
  });

  // ── Info grid ───────────────────────────────────────────────────────────────
  const gY    = 3.1;
  const rowH  = 0.55;
  const colX1 = 0.2, colX2 = 2.2;
  const labelC = ORANGE;
  const valueC = WHITE;

  const infoRows = [
    ["MEDIA TYPE",    row["Media"] || "—",               "ILLUMINATION",    row["Illumination"] || "—"],
    ["DIMENSIONS",    formatDim(row["W"], row["H"]),      "INSTALLATION",    formatCurrency(row["Installation cost"])],
    ["DISPLAY COST",  formatCurrency(row["Display cost per month"]), "PRODUCTION COST", formatCurrency(row["Production cost"])],
  ];

  infoRows.forEach((cols, r) => {
    const y = gY + r * rowH;
    slide.addText(cols[0], { x: colX1, y, w: 1.85, h: 0.2, fontSize: 6.5, bold: true, color: labelC, charSpacing: 1.5, margin: 0 });
    slide.addText(String(cols[1]), { x: colX1, y: y + 0.2, w: 1.85, h: 0.3, fontSize: 11, bold: true, color: valueC, margin: 0 });
    slide.addText(cols[2], { x: colX2, y, w: 1.85, h: 0.2, fontSize: 6.5, bold: true, color: labelC, charSpacing: 1.5, margin: 0 });
    slide.addText(String(cols[3]), { x: colX2, y: y + 0.2, w: 1.85, h: 0.3, fontSize: 11, bold: true, color: valueC, margin: 0 });
  });

  slide.addText("TOTAL COST", {
    x: 0.2, y: 4.72, w: 1.85, h: 0.2,
    fontSize: 6.5, bold: true, color: labelC, charSpacing: 1.5, margin: 0
  });
  slide.addText(formatCurrency(row["Total cost"]), {
    x: 0.2, y: 4.92, w: 1.85, h: 0.3,
    fontSize: 11, bold: true, color: valueC, margin: 0
  });

  // Divider before GPS
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.2, y: 5.55, w: leftW - 0.4, h: 0.025,
    fill: { color: "333333" }, line: { color: "333333" }
  });

  // ── GPS ─────────────────────────────────────────────────────────────────────
  slide.addText(`GPS  ${Number(lat).toFixed(6)}, ${Number(lng).toFixed(6)}`, {
    x: 0.2, y: 5.72, w: leftW - 0.3, h: 0.22,
    fontSize: 8, color: ORANGE, align: "left", margin: 0
  });

  // ── Map & Street View buttons ────────────────────────────────────────────────
  // Map View
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.2, y: 6.0, w: 1.78, h: 0.46,
    fill: { color: ORANGE }, line: { color: ORANGE }, shadow: mkShadow()
  });
  slide.addText("📍  Map View", {
    x: 0.2, y: 6.0, w: 1.78, h: 0.46,
    fontSize: 10, bold: true, color: WHITE, align: "center", valign: "middle",
    hyperlink: { url: mapUrl }, margin: 0
  });

  // Street View
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 2.13, y: 6.0, w: 1.78, h: 0.46,
    fill: { color: CHARCOAL }, line: { color: CHARCOAL }, shadow: mkShadow()
  });
  slide.addText("🏙  Street View", {
    x: 2.13, y: 6.0, w: 1.78, h: 0.46,
    fontSize: 10, bold: true, color: WHITE, align: "center", valign: "middle",
    hyperlink: { url: streetUrl }, margin: 0
  });

  // ── Bottom branding strip ────────────────────────────────────────────────────
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: SH - 0.38, w: leftW, h: 0.38,
    fill: { color: "111111" }, line: { color: "111111" }
  });
  slide.addText("OAP MEDIATECH", {
    x: 0.2, y: SH - 0.36, w: leftW - 0.25, h: 0.32,
    fontSize: 8, color: ORANGE, bold: true, charSpacing: 4, valign: "middle", margin: 0
  });

  // ── RIGHT PANEL ──────────────────────────────────────────────────────────────
  const rightX = PHOTO_X;
  const rightW = PHOTO_W;
  const photoH = PHOTO_H;

  // Visible frame around the real PowerPoint picture placeholder.
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: PHOTO_Y, w: rightW, h: photoH,
    fill: { color: LIGHT_GRAY, transparency: 100 }, line: { color: ORANGE, width: 1.5 }, shadow: mkShadow()
  });

  // "PHOTO" badge top-right corner
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX + rightW - 1.05, y: 0.15, w: 1.05, h: 0.3,
    fill: { color: ORANGE }, line: { color: ORANGE }
  });
  slide.addText("PHOTO", {
    x: rightX + rightW - 1.05, y: 0.15, w: 1.05, h: 0.3,
    fontSize: 7.5, bold: true, color: WHITE, align: "center", valign: "middle", charSpacing: 2, margin: 0
  });

  // Site number watermark in photo area
  slide.addText(`#${slideNum}`, {
    x: rightX + 0.3, y: 0.25, w: 0.8, h: 0.5,
    fontSize: 22, bold: true, color: "DDDDDD", align: "left", margin: 0
  });

  console.log(`   ✓ Slide ${slideNum} — ${row["City"] || ""} | ${(row["Location"] || "").substring(0,50)}`);
});

  return pres.write({ outputType: "blob" });
}

window.MediaPlanGenerator = {
  generateMediaPlanFromBuffer,
  generateMediaPlanFromRows,
  rowsFromExcelBuffer,
};

})();
